# Freeze the conv-codegen closure (ck_dsl + ck_dsl_provider modules, the embed
# shims, and the embedded arch_specs) generated by build_frozen.py. The directory
# is supplied by build_embed.py via the environment so the manifest stays
# location-independent.
import os

# Not named FROZEN_DIR: MicroPython's mkrules.mk reserves that make variable
# (removed feature) and errors if it appears in make's environment.
freeze(os.environ["CKDSL_FROZEN_DIR"])
